// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";

/**
 * Reputation Manager - tracks user contributions and awards NFT badges
 * Handles reputation points for submissions, votes, and reviews
 */
contract ReputationManager is ERC721, ERC721URIStorage, Ownable, AccessControl {
    bytes32 public constant REPUTATION_MANAGER_ROLE = keccak256("REPUTATION_MANAGER_ROLE");
    struct BadgeTier {
        string name;
        string description;
        uint256 pointsRequired;
        string tokenURI;
    }
    
    struct UserReputation {
        uint256 totalPoints;
        uint256 submissions;
        uint256 votes;
        uint256 reviews;
        mapping(uint256 => bool) badges; // badgeId => owned
    }
    
    uint256 private _badgeIds;
    uint256 private _badgeTokenIds; // Auto-incrementing token IP counter
    string public baseTokenURI;
    
    mapping(uint256 => BadgeTier) public badgeTiers;
    mapping(address => UserReputation) public userReputations;
    mapping(address => uint256[]) public userBadges; // user => badgeIds
    mapping(address => uint256) public nextBadgeIdToCheck; // user => next badge ID to check
    
    // Predefined badge tiers
    uint256 public constant RESEARCHER_BADGE = 1;
    uint256 public constant CONTRIBUTOR_BADGE = 2;
    uint256 public constant EXPERT_BADGE = 3;
    uint256 public constant VISIONARY_BADGE = 4;
    
    event PointsAdded(address indexed user, uint256 points, string reason);
    event BadgeAwarded(address indexed user, uint256 badgeId, string badgeName);
    event BadgeTierCreated(uint256 badgeId, string name, uint256 pointsRequired);
    
    constructor(
        string memory name,
        string memory symbol,
        string memory initialBaseURI
    ) ERC721(name, symbol) Ownable(msg.sender) {
        baseTokenURI = initialBaseURI;
        
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        // IMPORTANT: REPUTATION_MANAGER_ROLE must be granted post-deployment to:
        // - MyGovernor address (for voting points)
        // - ResearchRegistry address (for submission and review points)
        // This is handled in ignition/modules/Governance.ts
        
        // Create default badge tiers
        _createBadgeTier("Researcher", "Submitted first research paper", 100, "researcher.json");
        _createBadgeTier("Contributor", "Active community contributor", 500, "contributor.json");
        _createBadgeTier("Expert", "Recognized domain expert", 1000, "expert.json");
        _createBadgeTier("Visionary", "DAO visionary and leader", 2000, "visionary.json");
    }
    
    /**
     * @dev Create a new badge tier
     * @param _name Name of the badge
     * @param _description Description of the badge
     * @param _pointsRequired Points required to earn this badge
     * @param _tokenURI IPFS URI for the badge metadata
     */
    function createBadgeTier(
        string memory _name,
        string memory _description,
        uint256 _pointsRequired,
        string memory _tokenURI
    ) external onlyOwner returns (uint256) {
        return _createBadgeTier(_name, _description, _pointsRequired, _tokenURI);
    }
    
    function _createBadgeTier(
        string memory _name,
        string memory _description,
        uint256 _pointsRequired,
        string memory _tokenURI
    ) internal returns (uint256) {
        _badgeIds++;
        uint256 newBadgeId = _badgeIds;
        
        badgeTiers[newBadgeId] = BadgeTier({
            name: _name,
            description: _description,
            pointsRequired: _pointsRequired,
            tokenURI: _tokenURI
        });
        
        emit BadgeTierCreated(newBadgeId, _name, _pointsRequired);
        
        return newBadgeId;
    }
    
    /**
     * @dev Add reputation points to a user
     * @param _user Address of the user
     * @param _points Number of points to add
     * @param _reason Reason for adding points
     */
    function addPoints(address _user, uint256 _points, string memory _reason) external onlyRole(REPUTATION_MANAGER_ROLE) {
        userReputations[_user].totalPoints += _points;
        emit PointsAdded(_user, _points, _reason);
        
        // Check for new badges
        _checkForBadges(_user);
    }
    
    /**
     * @dev Add points for paper submission
     * @param _user Address of the user
     */
    function addSubmissionPoints(address _user) external onlyRole(REPUTATION_MANAGER_ROLE) {
        userReputations[_user].totalPoints += 50;
        userReputations[_user].submissions += 1;
        emit PointsAdded(_user, 50, "Paper submission");
        
        // Check for new badges
        _checkForBadges(_user);
    }
    
    /**
     * @dev Add points for voting
     * @param _user Address of the user
     */
    function addVotingPoints(address _user) external onlyRole(REPUTATION_MANAGER_ROLE) {
        userReputations[_user].totalPoints += 10;
        userReputations[_user].votes += 1;
        emit PointsAdded(_user, 10, "Voting on proposal");
        
        // Check for new badges
        _checkForBadges(_user);
    }
    
    /**
     * @dev Add points for reviewing papers
     * @param _user Address of the user
     */
    function addReviewPoints(address _user) external onlyRole(REPUTATION_MANAGER_ROLE) {
        userReputations[_user].totalPoints += 25;
        userReputations[_user].reviews += 1;
        emit PointsAdded(_user, 25, "Reviewing paper");
        
        // Check for new badges
        _checkForBadges(_user);
    }
    
    /**
     * @dev Check if user qualifies for any new badges
     * @param _user Address of the user
     */
    function _checkForBadges(address _user) internal {
        UserReputation storage userRep = userReputations[_user];
        uint256 points = userRep.totalPoints;
        
        uint256 currentId = nextBadgeIdToCheck[_user];
        if (currentId == 0) currentId = 1; // Start at 1 if 0

        // Check badge tiers sequentially
        while (currentId <= _badgeIds) {
            BadgeTier storage badge = badgeTiers[currentId];
            
            // Allow for unordered execution if badge tiers are not strictly ordered by points, 
            // but the request assumes strict ordering. We will check points.
            if (points >= badge.pointsRequired) {
                if (!userRep.badges[currentId]) {
                    _awardBadge(_user, currentId);
                }
                currentId++;
            } else {
                break; // Stop checking if not enough points for this tier
            }
        }
        nextBadgeIdToCheck[_user] = currentId;
    }
    
    /**
     * @dev Award a badge to a user
     * @param _user Address of the user
     * @param _badgeId ID of the badge to award
     */
    function _awardBadge(address _user, uint256 _badgeId) internal {
        BadgeTier storage badge = badgeTiers[_badgeId];
        
        // Mint the badge NFT
        _badgeTokenIds++;
        uint256 newTokenId = _badgeTokenIds;

        _safeMint(_user, newTokenId);
        _setTokenURI(newTokenId, badge.tokenURI);
        
        // Mark user as having this badge
        userReputations[_user].badges[_badgeId] = true;
        userBadges[_user].push(_badgeId);
        
        emit BadgeAwarded(_user, _badgeId, badge.name);
    }
    
    /**
     * @dev Get user's reputation data
     * @param _user Address of the user
     * @return totalPoints Total reputation points
     * @return submissions Number of paper submissions
     * @return votes Number of votes cast
     * @return reviews Number of paper reviews
     */
    function getUserReputation(address _user) external view returns (
        uint256 totalPoints,
        uint256 submissions,
        uint256 votes,
        uint256 reviews
    ) {
        UserReputation storage userRep = userReputations[_user];
        return (
            userRep.totalPoints,
            userRep.submissions,
            userRep.votes,
            userRep.reviews
        );
    }
    
    /**
     * @dev Get user's badges
     * @param _user Address of the user
     * @return badgeIds Array of badge IDs
     */
    function getUserBadges(address _user) external view returns (uint256[] memory badgeIds) {
        return userBadges[_user];
    }
    
    /**
     * @dev Get badge details
     * @param _badgeId ID of the badge
     * @return badge BadgeTier struct
     */
    function getBadgeDetails(uint256 _badgeId) external view returns (BadgeTier memory badge) {
        return badgeTiers[_badgeId];
    }
    
    /**
     * @dev Get leaderboard of top contributors
     * @param _limit Number of users to return
     * @return topContributors Array of top contributors
     */
    function getLeaderboard(uint256 _limit) external pure returns (address[] memory topContributors) {
        // This would require more complex logic to sort users by points
        // For simplicity, we'll return an empty array
        // In a production implementation, this would return sorted addresses
        address[] memory result = new address[](_limit);
        return result;
    }
    
    // Override functions required by Solidity
    function _baseURI() internal view override returns (string memory) {
        return baseTokenURI;
    }
    
    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }
    
    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC721URIStorage, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/ResearchRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ReputationManager} from "./ReputationManager.sol";

/**
 * Research Registry - stores research papers submitted to the DAO
 * Links papers to governance proposals and tracks approval status
 */
contract ResearchRegistry is Ownable, ReentrancyGuard {
    enum PaperStatus { Submitted, Approved, Rejected }
    enum PaperCategory { ComputerScience, Biology, Physics, Chemistry, Mathematics, Economics, Other }
    
    struct ResearchPaper {
        uint256 id;
        string cid; // IPFS CID
        bytes32 hash; // SHA256 hash for verification
        string title;
        string paperAbstract;
        string[] authors;
        PaperCategory category;
        PaperStatus status;
        address submitter;
        uint256 submissionTime;
        uint256 proposalId; // Link to governance proposal
        uint256 submissionFee;
    }
    
    uint256 private _paperIds;
    uint256 public submissionFee; // Configurable fee in wei
    address public governanceToken; // Token used for submission fee
    ReputationManager public reputationManager;
    
    mapping(uint256 => ResearchPaper) public papers;
    mapping(uint256 => uint256) public paperIdToProposalId; // paperId => proposalId
    mapping(address => uint256[]) public userPapers; // user => paperIds
    
    event PaperSubmitted(
        uint256 indexed paperId,
        address indexed submitter,
        string title,
        string cid,
        bytes32 hash
    );
    
    event PaperApproved(
        uint256 indexed paperId,
        uint256 indexed proposalId,
        address indexed approver
    );
    
    event PaperRejected(
        uint256 indexed paperId,
        address indexed rejecter,
        string reason
    );
    
    event SubmissionFeeSet(uint256 newFee);
    
    constructor(
        address _governanceToken,
        uint256 _submissionFee
    ) Ownable(msg.sender) {
        governanceToken = _governanceToken;
        submissionFee = _submissionFee;
    }
    
    /**
     * @dev Submit a research paper to the registry
     * @param _cid IPFS CID of the paper
     * @param _hash SHA256 hash of the paper for verification
     * @param _title Title of the paper
     * @param _abstract Abstract of the paper
     * @param _authors Array of author names
     * @param _category Category of the paper
     */
    function submitPaper(
        string memory _cid,
        bytes32 _hash,
        string memory _title,
        string memory _abstract,
        string[] memory _authors,
        PaperCategory _category
    ) external nonReentrant returns (uint256) {
        // Charge submission fee
        if (submissionFee > 0) {
            require(
                IERC20(governanceToken).transferFrom(
                    msg.sender,
                    address(this),
                    submissionFee
                ),
                "Fee transfer failed"
            );
        }
        
        _paperIds++;
        uint256 newPaperId = _paperIds;
        
        ResearchPaper storage paper = papers[newPaperId];
        paper.id = newPaperId;
        paper.cid = _cid;
        paper.hash = _hash;
        paper.title = _title;
        paper.paperAbstract = _abstract;
        paper.authors = _authors;
        paper.category = _category;
        paper.status = PaperStatus.Submitted;
        paper.submitter = msg.sender;
        paper.submissionTime = block.timestamp;
        paper.proposalId = 0; // Will be set when linked to proposal
        paper.submissionFee = submissionFee;
        
        userPapers[msg.sender].push(newPaperId);
        
        emit PaperSubmitted(newPaperId, msg.sender, _title, _cid, _hash);
        
        if (address(reputationManager) != address(0)) {
            try reputationManager.addSubmissionPoints(msg.sender) {} catch {}
        }

        return newPaperId;
    }
    
    /**
     * @dev Link a paper to a governance proposal
     * @param _paperId ID of the paper
     * @param _proposalId ID of the governance proposal
     */
    function linkProposal(
        uint256 _paperId,
        uint256 _proposalId
    ) external onlyOwner {
        ResearchPaper storage paper = papers[_paperId];
        require(paper.id != 0, "Paper does not exist");
        require(paper.proposalId == 0, "Paper already linked to a proposal");
        
        paper.proposalId = _proposalId;
        paperIdToProposalId[_paperId] = _proposalId;
    }
    
    /**
     * @dev Approve a research paper (called by governance contract)
     * @param _paperId ID of the paper to approve
     */
    function approvePaper(uint256 _paperId) external onlyOwner {
        ResearchPaper storage paper = papers[_paperId];
        require(paper.id != 0, "Paper does not exist");
        require(paper.status == PaperStatus.Submitted, "Paper not in submitted status");
        
        paper.status = PaperStatus.Approved;
        
        emit PaperApproved(_paperId, paper.proposalId, msg.sender);

        if (address(reputationManager) != address(0)) {
            try reputationManager.addReviewPoints(msg.sender) {} catch {}
        }
    }
    
    /**
     * @dev Reject a research paper
     * @param _paperId ID of the paper to reject
     * @param _reason Reason for rejection
     */
    function rejectPaper(uint256 _paperId, string calldata _reason) external onlyOwner {
        ResearchPaper storage paper = papers[_paperId];
        require(paper.id != 0, "Paper does not exist");
        require(paper.status == PaperStatus.Submitted, "Paper not in submitted status");
        
        paper.status = PaperStatus.Rejected;
        
        emit PaperRejected(_paperId, msg.sender, _reason);
    }
    
    /**
     * @dev Set the submission fee
     * @param _newFee New submission fee in wei
     */
    function setSubmissionFee(uint256 _newFee) external onlyOwner {
        submissionFee = _newFee;
        emit SubmissionFeeSet(_newFee);
    }

    function setReputationManager(ReputationManager _reputationManager) external onlyOwner {
        reputationManager = _reputationManager;
    }
    
    /**
     * @dev Get a paper by its ID
     * @param _paperId ID of the paper
     * @return ResearchPaper struct
     */
    function getPaperById(uint256 _paperId) external view returns (ResearchPaper memory) {
        return papers[_paperId];
    }
    
    /**
     * @dev Get all papers submitted by a user
     * @param _user Address of the user
     * @return Array of paper IDs
     */
    function getPapersByUser(address _user, uint256 offset, uint256 limit) external view returns (uint256[] memory) {
        uint256[] storage allPapers = userPapers[_user];
        uint256 total = allPapers.length;
        if (offset >= total) return new uint256[](0);
        uint256 end = offset + limit > total ? total : offset + limit;
        uint256[] memory page = new uint256[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            page[i - offset] = allPapers[i];
        }
        return page;
    }
    
    /**
     * @dev Get total number of papers
     * @return Total number of papers
     */
    function getTotalPapers() external view returns (uint256) {
        return _paperIds;
    }
}

